# Generated by opencode (deepseek-v4-flash) on 2026-09-11.
# Builds the LaTeX results tables from an eval/*.txt file produced by
# eval.py / plot.py. The datasets are split into two tabular tables (first three
# datasets, then the last two), each scaled to \textwidth with \resizebox. Usage:
#     python src/make_results_table.py [input_txt] [output_tex]
# Defaults to eval/table.txt; prints to stdout when no output path is given.
# Required LaTeX packages: booktabs, multirow, xcolor (table option), arydshln, graphicx.

import os
import sys

in_path = sys.argv[1] if len(sys.argv) > 1 else "eval/table.txt"
out_path = sys.argv[2] if len(sys.argv) > 2 else None
raw = open(in_path).read()

_stem = os.path.splitext(os.path.basename(in_path))[0]
_suffix = _stem.replace("table", "").strip("_")
LABEL_BASE = "tab:gp_results" + (f"_{_suffix}" if _suffix else "")

DATASETS = ["Wine", "Protein", "Parkinsons", "KEGGu", "Road"]
DIMS = {"Wine": 11, "Protein": 9, "Parkinsons": 19, "KEGGu": 24, "Road": 2}

records = []
cur = None
for line in raw.splitlines():
    line = line.strip()
    if not line:
        continue
    if not line.startswith(tuple(DATASETS)):
        toks = line.split()
        sv = "SV" in toks
        opt = next((t for t in toks if t in ("Adam", "LBFGS")), "Adam")
        gp = " ".join(t for t in toks if t not in ("Adam", "LBFGS", "SV"))
        cur = (gp, opt, sv)
    else:
        parts = [x.strip() for x in line.split(",")]
        ln, rm, rs, nm, ns, rt, p50, p90, p95 = (float(x) for x in parts[1:])
        records.append((cur, parts[0], [rm, rs, nm, ns, p50, p90, p95, rt]))

GPSEQ = ["Exact", "ExactCG", "SVGP random", "SVGP kmeans", "CAGP"]
OPTS = {"Exact": ["Adam", "LBFGS"], "ExactCG": ["Adam", "LBFGS"],
        "SVGP random": ["Adam"], "SVGP kmeans": ["Adam"], "CAGP": ["Adam"]}


def label(gp):
    if gp.startswith("SVGP"):
        return "SVGP (" + ("random init." if "random" in gp else "k-means init.") + ")"
    return {"Exact": "ExactGP", "ExactCG": "CGGP", "CAGP": "CAGP"}[gp]


by = {}
for (gp, opt, sv), ds, vals in records:
    by.setdefault(ds, []).append((gp, opt, sv, vals))


def rows_for(ds):
    out = []
    for gp in GPSEQ:
        for opt in OPTS[gp]:
            rs = [r for r in by[ds] if r[0] == gp and r[1] == opt]
            rs.sort(key=lambda r: not r[2])
            out.extend(rs)
    return out


COLORS = ["gold", "silver", "bronze"]
FMTS = ["{:.3f}", "{:.4f}", "{:.3f}", "{:.4f}", "{:.3f}", "{:.3f}", "{:.3f}", "{:.1f}"]
COLOR_MASK = [True, False, True, False, False, False, False, True]


def color_assign(vals):
    order = sorted(range(len(vals)), key=lambda i: vals[i])
    cols = [None] * len(vals)
    for rank, idx in enumerate(order[:3]):
        cols[idx] = COLORS[rank]
    return cols


SPLITS = [DATASETS[:3], DATASETS[3:]]


def build_body(dss):
    body = []
    for di, ds in enumerate(dss):
        rows = rows_for(ds)
        colors = [color_assign([r[3][m] for r in rows]) for m in range(len(FMTS))]
        for ri, (gp, opt, sv, metric_vals) in enumerate(rows):
            cells = []
            if ri == 0:
                cells.append(f"\\multirow{{{len(rows)}}}{{*}}{{{ds}}}")
                cells.append(f"\\multirow{{{len(rows)}}}{{*}}{{{DIMS[ds]}}}")
            else:
                cells += ["", ""]
            if ri == 0 or gp != rows[ri - 1][0]:
                span = sum(1 for r in rows if r[0] == gp)
                cells.append(f"\\multirow{{{span}}}{{*}}{{{label(gp)}}}")
            else:
                cells.append("")
            cells.append(opt)
            cells.append("Yes" if sv else "No")
            for m in range(len(FMTS)):
                s = FMTS[m].format(metric_vals[m])
                if COLOR_MASK[m] and colors[m][ri]:
                    s = f"\\cellcolor{{{colors[m][ri]}}}{s}"
                cells.append(s)
            line = " & ".join(cells) + " \\\\"
            if ri < len(rows) - 1 and rows[ri + 1][0] != gp:
                line += " \\cdashline{3-13}"
            body.append(line)
        if di < len(dss) - 1:
            body.append("\\midrule")
    return body

head = [
    "\\toprule",
    "\\multirow{2}{*}{Dataset} & \\multirow{2}{*}{$d$} & \\multirow{2}{*}{GP Method} & \\multirow{2}{*}{Optimizer} & \\multirow{2}{*}{OS trained} & \\multicolumn{2}{c}{RMSE} & \\multicolumn{2}{c}{NLL} & \\multicolumn{3}{c}{PICP} & \\multirow{2}{*}{Time (s)}\\\\",
    "\\cmidrule(lr){6-7}\\cmidrule(lr){8-9}\\cmidrule(lr){10-12}",
    " & & & & & mean & std & mean & std & 50 & 90 & 95 & \\\\",
    "\\midrule",
]

out = []
out.append("{\\footnotesize")
out.append("\\setlength{\\tabcolsep}{5.5pt}")

for ti, dss in enumerate(SPLITS, start=1):
    names = ", ".join(dss)
    caption = (
        "\\caption{Mean test-set metrics over 5 seeds for each configuration and dataset "
        f"({names}). RMSE and NLL are reported as mean and standard deviation, "
        "PICP50/90/95 their empirical coverage; runtime in seconds. Best three values "
        "per dataset and metric are highlighted in gold, silver and bronze; standard "
        "deviations are not highlighted.}"
    )
    out.append("\\begin{table}[htbp]")
    out.append("\\centering")
    out.append(caption)
    out.append(f"\\label{{{LABEL_BASE}_{ti}}}")
    out.append("\\resizebox{\\textwidth}{!}{%")
    out.append("\\begin{tabular}{@{}llccccccccccc@{}}")
    out.extend(head)
    out.extend(build_body(dss))
    out.append("\\bottomrule")
    out.append("\\end{tabular}%")
    out.append("}")
    out.append("\\end{table}")

out.append("}")

text = "\n".join(out)
if out_path:
    with open(out_path, "w") as f:
        f.write(text + "\n")
else:
    print(text)
